import os, json

BASE = 'storage/shared/atlas/analysis/cross_lineage/meta_edge_monitor'
INP  = os.path.join(BASE, 'predictive_scenarios_summary_corr.json')
OUTJ = os.path.join(BASE, 'ci_corr_report.json')     # overwrite prior
OUTT = os.path.join(BASE, 'ci_corr_report.txt')

def load_json(p):
    if not os.path.exists(p): return None
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except Exception:
        return None

def in_01(x): return (0.0 <= x <= 1.0)

def nondecreasing(a, tol=1e-9):
    return all(a[i+1] + tol >= a[i] for i in range(len(a)-1))

def write_reports(rep):
    os.makedirs(BASE, exist_ok=True)
    with open(OUTJ,'w',encoding='utf-8') as f: json.dump(rep, f, ensure_ascii=False, indent=2)
    with open(OUTT,'w',encoding='utf-8') as f:
        f.write(f"version: {rep.get('version')}\n")
        f.write(f"status: {'OK' if rep.get('ok') else 'FAIL'}\n")
        for k in ['horizons','len_any','len_all','len_one']:
            if k in rep: f.write(f"{k}: {rep[k]}\n")
        for k in ['checks','notes','errors','warnings']:
            if k in rep:
                f.write(f"{k}: {rep[k]}\n")
    print(json.dumps({"status":"ok","report_json":OUTJ,"report_txt":OUTT,"ok":rep.get('ok',False),"version":rep.get('version')}))

def main():
    d = load_json(INP)
    rep = {"version": "1.1", "input": INP, "ok": False, "errors": [], "warnings": [], "checks": []}
    if not isinstance(d, dict):
        rep["errors"].append("input_not_json_dict")
        return write_reports(rep)

    # Determine H
    H = None
    if "horizons" in d and isinstance(d["horizons"], list): H = len(d["horizons"])
    elif "horizons" in d and isinstance(d["horizons"], int): H = int(d["horizons"])
    elif "H" in d and isinstance(d["H"], int): H = int(d["H"])
    if not H or H < 1:
        rep["errors"].append("invalid_or_missing_horizons")
        return write_reports(rep)
    rep["horizons"] = H

    # Arrays
    keys = {
      "any": "p_any_corr",
      "all": "p_all_corr",
      "one": "p_exactly_one_corr"
    }
    arr = {}
    for name, key in keys.items():
        v = d.get(key)
        if not isinstance(v, list) or len(v) != H:
            rep["errors"].append(f"missing_or_wrong_length:{key}")
        else:
            try:
                arr[name] = [float(x) for x in v]
            except Exception:
                rep["errors"].append(f"non_numeric:{key}")
    if rep["errors"]:
        return write_reports(rep)

    rep["len_any"], rep["len_all"], rep["len_one"] = len(arr["any"]), len(arr["all"]), len(arr["one"])

    # Bounds
    for name in ["any","all","one"]:
        bad = [i for i,x in enumerate(arr[name]) if not in_01(x)]
        if bad:
            rep["errors"].append(f"out_of_bounds:{name}:{bad[:5]}{'...' if len(bad)>5 else ''}")
        else:
            rep["checks"].append(f"bounds_ok:{name}")

    # P(all) ≤ P(any)
    comp_bad = [i for i,(a,an) in enumerate(zip(arr["all"], arr["any"])) if a > an + 1e-9]
    if comp_bad:
        rep["warnings"].append(f"all_exceeds_any_at:{comp_bad[:5]}{'...' if len(comp_bad)>5 else ''}")
    else:
        rep["checks"].append("all_le_any_ok")

    # Monotonicity across horizons (non-decreasing for any/all)
    if nondecreasing(arr["any"]):
        rep["checks"].append("monotone_nondecreasing:any")
    else:
        rep["warnings"].append("non_monotone:any")
    if nondecreasing(arr["all"]):
        rep["checks"].append("monotone_nondecreasing:all")
    else:
        rep["warnings"].append("non_monotone:all")

    rep["ok"] = len(rep["errors"]) == 0
    rep["notes"] = "CI v1.1 adds monotonicity checks for P(any)_corr and P(all)_corr across horizons."
    return write_reports(rep)

if __name__ == "__main__":
    main()
